std::string FormatDouble(double value)
{
    std::ostringstream stream;
    stream << std::fixed << std::setprecision(4) << value;
    return stream.str();
}

std::string FormatTag(tag_t tag)
{
    std::ostringstream stream;
    stream << static_cast<unsigned long long>(tag);
    return stream.str();
}

std::string FormatTagList(const std::vector<tag_t>& tags)
{
    std::ostringstream stream;
    for (std::size_t index = 0; index < tags.size(); ++index)
    {
        if (index > 0)
        {
            stream << ",";
        }
        stream << static_cast<unsigned long long>(tags[index]);
    }
    return stream.str();
}

std::string FormatSideMap(const std::map<tag_t, int>& sideByFace)
{
    std::ostringstream stream;
    bool first = true;
    for (std::map<tag_t, int>::const_iterator sideIt = sideByFace.begin();
        sideIt != sideByFace.end();
        ++sideIt)
    {
        if (!first)
        {
            stream << ",";
        }
        first = false;
        stream << static_cast<unsigned long long>(sideIt->first)
            << ":" << sideIt->second;
    }
    return stream.str();
}

std::string FormatVector3(const double value[3])
{
    std::ostringstream stream;
    stream << "("
        << FormatDouble(value[0]) << ", "
        << FormatDouble(value[1]) << ", "
        << FormatDouble(value[2]) << ")";
    return stream.str();
}

void DebugLog(const std::string& message)
{
    if (!kDebugLogEnabled)
    {
        return;
    }

    CreateDirectoryW(L"D:\\UG智辉钣金插件\\logs", NULL);
    static bool resetForThisRun = false;
    if (!resetForThisRun)
    {
        ResetDebugLogForRun();
        resetForThisRun = true;
    }

    SYSTEMTIME now = {};
    GetLocalTime(&now);

    std::ostringstream line;
    line << std::setfill('0')
        << now.wYear << "-"
        << std::setw(2) << now.wMonth << "-"
        << std::setw(2) << now.wDay << " "
        << std::setw(2) << now.wHour << ":"
        << std::setw(2) << now.wMinute << ":"
        << std::setw(2) << now.wSecond << "."
        << std::setw(3) << now.wMilliseconds
        << " " << message << "\n";

    HANDLE file = CreateFileW(
        kDebugLogPath,
        FILE_APPEND_DATA,
        FILE_SHARE_READ | FILE_SHARE_WRITE,
        NULL,
        OPEN_ALWAYS,
        FILE_ATTRIBUTE_NORMAL,
        NULL);
    if (file == INVALID_HANDLE_VALUE)
    {
        return;
    }

    const std::string text = line.str();
    DWORD written = 0;
    WriteFile(file, text.data(), static_cast<DWORD>(text.size()), &written, NULL);
    CloseHandle(file);
}

