TianFenXI::TianFenXI()
{
    try
    {
        // Initialize the NX Open C++ API environment
        TianFenXI::theSession = NXOpen::Session::GetSession();
        TianFenXI::theUI = UI::GetUI();
        const std::string dlxPath = zhihui_embedded_dialog::ExtractDlxToRandomPath(IDR_ZH_DLX_TIANFENXI_DLX);
        if (dlxPath.empty())
        {
            throw std::runtime_error("TianFenXI dialog resource is missing.");
        }
        theDlxFileName = NULL;
        previewSelectedFaceTag = NULL_TAG;
        updatingSelectionProgrammatically = false;
        hasPreviewThickness = false;
        previewThickness = 0.0;
        previewInwardNormal[0] = 0.0;
        previewInwardNormal[1] = 0.0;
        previewInwardNormal[2] = 0.0;
        theDialog = TianFenXI::theUI->CreateDialog(dlxPath.c_str());
        // Registration of callback functions
        theDialog->AddApplyHandler(make_callback(this, &TianFenXI::apply_cb));
        theDialog->AddOkHandler(make_callback(this, &TianFenXI::ok_cb));
        theDialog->AddUpdateHandler(make_callback(this, &TianFenXI::update_cb));
        theDialog->AddInitializeHandler(make_callback(this, &TianFenXI::initialize_cb));
        theDialog->AddDialogShownHandler(make_callback(this, &TianFenXI::dialogShown_cb));
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        throw;
    }
}

