//------------------------------------------------------------------------------
//Callback Name: apply_cb
//------------------------------------------------------------------------------
int TianFenXI::apply_cb()
{
    int errorCode = 0;
    try
    {
        ResetDebugLogForRun();
        DebugLog("Apply clicked");
        gLastGapDeleteFailedGroups = 0;
        gLastGapDeleteSucceededGroups = 0;
        gLastGapDeleteFailedGroupIndexes.clear();
        SaveUiSettings();
        {
            SilentDisplayUpdateGuard silentDisplayGuard;
            PreviewSelectedFaceChain(true);
            DebugLog("Remove parameters temporarily disabled for feature-tree diagnosis");
        }
        if (gLastGapDeleteFailedGroups > 0 && gLastGapDeleteSucceededGroups == 0)
        {
            const std::string message = "删除缝隙失败，失败组数=" +
                FormatTag(static_cast<tag_t>(gLastGapDeleteFailedGroups)) +
                "，组=[" + FormatTagList(gLastGapDeleteFailedGroupIndexes) + "]。";
            DebugLog("Apply gap delete failed UI message: " + message);
            TianFenXI::theUI->NXMessageBox()->Show(
                "天缝隙",
                NXOpen::NXMessageBox::DialogTypeWarning,
                message.c_str());
        }
        DebugLog("Apply preview and middle plane creation done");
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        TianFenXI::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

//------------------------------------------------------------------------------
//Callback Name: update_cb
//------------------------------------------------------------------------------
int TianFenXI::update_cb(NXOpen::BlockStyler::UIBlock* block)
{
    try
    {
        if(block == selection0)
        {
            if (updatingSelectionProgrammatically)
            {
                DebugLog("Selection update ignored: programmatic rewrite");
            }
            else
            {
                PreviewSelectedFaceChain();
            }
        }
        else if(block == string0)
        {
            SaveUiSettings();
            userDeselectedGapFaces.clear();
            PreviewSelectedFaceChain();
        }
        else if(block == toggle0)
        {
            UpdateDeleteRVisibility();
            SaveUiSettings();
        }
        else if(block == string01)
        {
            SaveUiSettings();
        }
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        TianFenXI::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return 0;
}

//------------------------------------------------------------------------------
//Callback Name: ok_cb
//------------------------------------------------------------------------------
int TianFenXI::ok_cb()
{
    int errorCode = 0;
    try
    {
        errorCode = apply_cb();
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        TianFenXI::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}
